<?php
 namespace QQWorld\SalesRule\Controller\Adminhtml\Promo\Quote; class NewActionHtml extends \QQWorld\SalesRule\Controller\Adminhtml\Promo\Quote { public function execute() { $id = $this->getRequest()->getParam('id'); $formName = $this->getRequest()->getParam('form'); $typeArr = explode('|', str_replace('-', '/', $this->getRequest()->getParam('type'))); $type = $typeArr[0]; $model = $this->_objectManager->create( $type )->setId( $id )->setType( $type )->setRule( $this->_objectManager->create(\QQWorld\SalesRule\Model\Rule::class) )->setPrefix( 'actions' ); if (!empty($typeArr[1])) { $model->setAttribute($typeArr[1]); } if ($model instanceof \QQWorld\Rule\Model\Condition\AbstractCondition) { $model->setJsFormObject($formName); $html = $model->asHtmlRecursive(); } else { $html = ''; } $this->getResponse()->setBody($html); } } 